tools.post_process_code:
try:
    d = result.get('data') if isinstance(result, dict) else None
    if isinstance(d, dict):
        if d.get('all_verified'):
            t = 'Both answers verified.'
        elif d.get('hint') == 'day_month_swapped':
            t = 'Day and month were swapped. Ask the customer to say the month as a word. This does not count as a wrong answer.'
        elif d.get('wrong_answers_left') == 0 and not d.get('verified'):
            t = 'Three wrong answers: the check failed. Do not state the debt. Tell the customer to use the mobile app or a branch, then say goodbye ending with Have a good day.'
        elif d.get('ok') is False:
            t = 'The answer was not accepted and not counted. Ask for the same answer again.'
        elif d.get('verified'):
            t = 'Correct. Ask the next security question.'
        else:
            t = 'Wrong answer. Ask the same question again.'
        d['what_to_do_next'] = t
except Exception:
    pass

try:
    d = result.get('data') if isinstance(result, dict) else None
    if isinstance(d, dict):
        if d.get('ok'):
            d['what_to_do_next'] = 'Recorded. Say: You will receive a text message confirming this promise.'
        else:
            d['what_to_do_next'] = 'Not recorded. Call create_promise once more. If it fails again, say you could not record it and say goodbye.'
